export const CACHE_CAP = 64;

/**
 * Default flat-plane chunk builder: a chunkSize x chunkSize horizontal plane
 * centered at world (cx * chunkSize, 0, cz * chunkSize).
 */
function makeDefaultBuilder(chunkSize) {
  return function buildChunk(cx, cz) {
    const geometry = new THREE.PlaneGeometry(chunkSize, chunkSize);
    geometry.rotateX(-Math.PI / 2);
    const mesh = new THREE.Mesh(geometry);
    mesh.position.set(cx * chunkSize, 0, cz * chunkSize);
    mesh.updateMatrix();
    return mesh;
  };
}

/**
 * Creates a chunk streaming manager.
 *
 * @param {object} [options]
 * @param {number} [options.chunkSize=16] - World units per chunk edge.
 * @param {number} [options.radius=2] - Active Chebyshev radius in chunks.
 * @param {(cx: number, cz: number) => THREE.Mesh} [options.buildChunk]
 * @returns manager object with `.group` (attach/detach target), `.cache`
 *          (key -> Mesh, LRU ordered, capped at CACHE_CAP) and `.active`
 *          (Set of currently attached chunk keys).
 */
export function createChunkManager({
  chunkSize = 16,
  radius = 2,
  buildChunk,
} = {}) {
  if (typeof buildChunk !== 'function') {
    buildChunk = makeDefaultBuilder(chunkSize);
  }
  return {
    group: new THREE.Group(),
    chunkSize,
    radius,
    buildChunk,
    cache: new Map(), // insertion order = LRU order (oldest first)
    active: new Set(),
  };
}

function keyOf(cx, cz) {
  return `${cx},${cz}`;
}

/**
 * Ensures exactly the chunks within Chebyshev distance `radius` (in chunk
 * coords) of (cameraX, cameraZ) are attached to mgr.group:
 *  - builds + attaches missing chunks (or reattaches cached ones),
 *  - detaches out-of-range chunks (kept in the LRU cache, not disposed),
 *  - evicts the least-recently-used cached chunks beyond the cap,
 *    disposing their geometry.
 */
export function updateChunks(mgr, cameraX, cameraZ) {
  const { chunkSize, radius, group, cache } = mgr;

  const ccx = Math.floor(cameraX / chunkSize);
  const ccz = Math.floor(cameraZ / chunkSize);

  const wanted = new Set();

  for (let dx = -radius; dx <= radius; dx++) {
    for (let dz = -radius; dz <= radius; dz++) {
      const cx = ccx + dx;
      const cz = ccz + dz;
      const key = keyOf(cx, cz);
      wanted.add(key);

      let mesh = cache.get(key);
      if (mesh) {
        // LRU refresh: most recently used goes last.
        cache.delete(key);
        cache.set(key, mesh);
      } else {
        mesh = mgr.buildChunk(cx, cz);
        mesh.userData.chunkKey = key;
        cache.set(key, mesh);
      }

      if (!mesh.parent || mesh.parent !== group) {
        group.add(mesh);
      }
    }
  }

  // Detach chunks that fell out of range (stay cached for reuse).
  for (const [, mesh] of cache) {
    if (!wanted.has(mesh.userData.chunkKey) && mesh.parent === group) {
      group.remove(mesh);
    }
  }

  // Evict oldest cached chunks beyond the cap.
  while (cache.size > CACHE_CAP) {
    const oldestKey = cache.keys().next().value;
    const mesh = cache.get(oldestKey);
    cache.delete(oldestKey);
    if (mesh.parent) mesh.parent.remove(mesh);
    if (mesh.geometry && typeof mesh.geometry.dispose === 'function') {
      mesh.geometry.dispose();
    }
  }

  mgr.active = wanted;
}

/** Sorted list of "cx,cz" keys for currently attached chunks. */
export function activeKeys(mgr) {
  return [...mgr.active].sort((a, b) => {
    const [ax, az] = a.split(',').map(Number);
    const [bx, bz] = b.split(',').map(Number);
    return ax - bx || az - bz;
  });
}
"})
