result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/chunks.test.js", "content": "import { describe, it, expect, vi } from 'vitest';
import * as THREE from 'three';
import { createChunkManager, updateChunks, activeKeys } from '../src/chunks.js';

/** Builder whose geometries carry dispose spies, for eviction testing. */
function makeSpyBuilder(record) {
  return vi.fn((cx, cz) => {
    const geometry = new THREE.BufferGeometry();
    const dispose = vi.spyOn(geometry, 'dispose');
    const mesh = new THREE.Mesh(geometry);
    record.meshes.push(mesh);
    record.disposes.push(dispose);
    return mesh;
  });
}

describe('createChunkManager / updateChunks', () => {
  it('activates exactly the 5x5 grid around (0,0) with radius 2', () => {
    const mgr = createChunkManager();
    updateChunks(mgr, 0, 0);

    const keys = activeKeys(mgr);
    expect(keys).toHaveLength(25);
    expect(keys[12]).toBe('0,0');

    const expected = [];
    for (let cx = -2; cx <= 2; cx++)
      for (let cz = -2; cz <= 2; cz++) expected.push(`${cx},${cz}`);
    expected.sort();
    expect(keys).toEqual(expected);

    expect(mgr.group.children).toHaveLength(25);
  });

  it('stepping one chunk in +x swaps the far column for a near column', () => {
    const mgr = createChunkManager();
    updateChunks(mgr, 0, 0);
    const before = new Set(activeKeys(mgr));

    updateChunks(mgr, 16, 0); // exactly one chunk east
    const after = new Set(activeKeys(mgr));

    // Dropped column cx = -2, added column cx = 3.
    const dropped = [...before].filter((k) => !after.has(k)).sort();
    const added = [...after].filter((k) => !before.has(k)).sort();

    expect(dropped.sort()).toEqual(['-2,-2', '-2,-1', '-2,0', '-2,1', '-2,2']);
    expect(added.sort()).toEqual(['3,-2', '3,-1', '3,0', '3,1', '3,2']);

    // Exact comparison against the full expected set.
    const expected = [];
    for (let cx = -1; cx <= 3; cx++)
      for (let cz = -2; cz <= 2; cz++) expected.push(`${cx},${cz}`);
    expected.sort();
    expect([...after].sort()).toEqual(expected);
    expect(after.size).toBe(25);
    expect(mgr.group.children).toHaveLength(25);
  });

  it('revisiting a cached chunk reuses the same Mesh instance', () => {
    const mgr = createChunkManager();
    updateChunks(mgr, 0, 0);
    const original = mgr.group.children.find(
      (m) => m.userData.chunkKey === '0,0'
    );
    expect(original).toBeDefined();

    // Walk 7 chunks east (cache grows to 25 + 5*7 = 60 < 64, no eviction),
    // then walk back to the origin.
    for (let i = 1; i <= 7; i++) updateChunks(mgr, i * 16, 0);
    for (let i = 6; i >= 0; i--) updateChunks(mgr, i * 16, 0);

    const revived = mgr.group.children.find(
      (m) => m.userData.chunkKey === '0,0'
    );
    expect(revived).toBe(original);
    expect(mgr.group.children).toHaveLength(25);
  });

  it('evicts the oldest cached chunks past 64 and disposes their geometry', () => {
    const record = { meshes: [], disposes: [] };
    const buildChunk = makeSpyBuilder(record);
    const mgr = createChunkManager({ buildChunk });
    updateChunks(mgr, 0, 0);

    // March east: each step caches 5 new chunks, dropping 5 behind.
    // After 12 steps: 25 + 60 = 85 distinct chunks -> 21 must be evicted.
    for (let i = 1; i <= 12; i++) updateChunks(mgr, i * 16, 0);

    expect(mgr.cache.size).toBeLessThanOrEqual(64);

    const totalDisposes = record.disposes.reduce(
      (n, d) => n + d.mock.calls.length,
      0
    );
    expect(buildChunk).toHaveBeenCalledTimes(85);
    expect(totalDisposes).toBeGreaterThan(0);
    expect(totalDisposes).toBe(25 + 5 * 12 - 64);

    // No attached (active) chunk may have been disposed.
    const activeDisposed = mgr.group.children.filter((mesh) =>
      record.disposes[
        record.meshes.indexOf(mesh)
      ]?.mock.calls.length
    );
    expect(activeDisposed).toHaveLength(0);
  });
});
"})
